    expect(logout.status).toBe(403);
    expect(browser.cookies.has(SESSION_COOKIE)).toBe(true);
    expect(world.index.revoked.size).toBe(0);
    expect(world.workos.revokedSessions.size).toBe(0);
  });

  it("revokes the session at WorkOS too on sign-out", async () => {
    const { world, browser } = await signedIn();
    await browser.fetch("/auth/logout", { method: "POST", headers: { origin: ORIGIN } });
    expect([...world.index.revoked]).toEqual([...world.workos.revokedSessions]);
    expect(world.workos.revokedSessions.size).toBe(1);
  });

  it("signs out a session whose access token expired", async () => {
    const { world, browser } = await signedIn();
    world.workos.expire(browser.cookies.get(SESSION_COOKIE) ?? "");
    const logout = await browser.fetch("/auth/logout", { method: "POST", headers: { origin: ORIGIN } });
    expect(logout.status).toBe(303);
    expect(logout.headers.get("location")).toMatch(
      /^https:\/\/auth\.example\.test\/logout\?session_id=session_/,
    );
    expect(browser.cookies.has(SESSION_COOKIE)).toBe(false);
    expect(world.index.revoked.size).toBe(1);
    expect(world.workos.revokedSessions.size).toBe(1);
  });

  it("answers 503 when WorkOS cannot revoke, after denying the session and dropping the cookie", async () => {
    const { world, browser, newBrowser } = await signedIn();
    const stolen = browser.cookies.get(SESSION_COOKIE) ?? "";
    world.workos.failRevokeSession = true;
    const logout = await browser.fetch("/auth/logout", { method: "POST", headers: { origin: ORIGIN } });
    expect(logout.status).toBe(503);
    expect(browser.cookies.has(SESSION_COOKIE)).toBe(false);
    const replay = newBrowser();
    replay.cookies.set(SESSION_COOKIE, stolen);
    expect((await replay.session()).status).toBe(401);
  });

  it("refuses state-changing requests from another origin", async () => {
    const { world, browser } = setup("ops@example.com");
    await browser.signIn(world.workos.addUser("ops@example.com"));
    const response = await browser.post(
      "/auth/organization",
      { name: "Acme" },
      "https://pr-1.submit.surveybeat.app",
    );
    expect(response.status).toBe(403);
    expect(world.workos.createOrganizationCalls).toBe(0);
  });
});

import type * as Arbitrary from "effect/Arbitrary";
import type { HttpApi, HttpApiGroup } from "effect/http-api";
import type { SurveyBeatApi } from "./index.ts";

/** `group.endpoint` for every endpoint of an HttpApi declaration. */
export type EndpointKey<Api> =
  Api extends HttpApi.HttpApi<infer _Id, infer Groups>
    ? Groups extends HttpApiGroup.Constraint
      ? `${Groups["identifier"]}.${HttpApiGroup.Endpoints<Groups>["identifier"]}`
      : never
    : never;

/**
 * Whether an endpoint's response can contain Result data (scores, distributions, comments, trends:
 * anything derived from Submissions). Those endpoints get an input generator that produces Rounds,
 * and a property test checks the minimum group size rules R1–R11 (ADR 0004) for each of them.
 */
export type EndpointPrivacy =
  | { readonly _tag: "NoResultData"; readonly why: string }
  | { readonly _tag: "ResultData"; readonly inputs: Arbitrary.Arbitrary<unknown> };

/**
 * Every endpoint of `SurveyBeatApi`, classified. A new endpoint does not typecheck until it is
 * listed here, and `registry.privacy.test.ts` checks the same against the runtime declaration.
 */
export const privacyRegistry: { readonly [K in EndpointKey<typeof SurveyBeatApi>]: EndpointPrivacy } = {
  "organizations.create": { _tag: "NoResultData", why: "returns the Organization's id and name" },
  "organizations.getById": { _tag: "NoResultData", why: "returns the Organization's id and name" },
  "auth.login": { _tag: "NoResultData", why: "redirects to the AuthKit hosted sign-in page" },
  "auth.callback": { _tag: "NoResultData", why: "sets the session cookie and redirects to the app" },
  "auth.logout": { _tag: "NoResultData", why: "clears the session cookie and redirects to WorkOS logout" },
  "auth.session": {
    _tag: "NoResultData",
    why: "returns the sign-in state: Organization ids and names, a Person id, and the admin flag",
  },
  "auth.createOrganization": {
    _tag: "NoResultData",
    why: "returns the sign-in state of the new Organization's admin",
  },
  "auth.chooseOrganization": {
    _tag: "NoResultData",
    why: "returns the sign-in state in the chosen Organization",
  },
};
import { assert, layer } from "@effect/vitest";
import { Effect, Layer, Ref } from "effect";
import { HttpServer } from "effect/http";
import { HttpApiBuilder, HttpApiTest } from "effect/http-api";
import { Organization, OrganizationId, OrganizationNotFound } from "@surveybeat/domain";
import { SurveyBeatApi } from "./index.ts";

// In-memory handlers: no database and no HTTP server.
const OrganizationsHandlers = HttpApiBuilder.group(
  SurveyBeatApi,
  "organizations",
  Effect.fn(function* (handlers) {
    const store = yield* Ref.make(new Map<string, Organization>());
    return handlers
      .handle("create", ({ payload }) =>
        Ref.modify(store, (organizations) => {
          const organization = new Organization({
            id: OrganizationId.make(`org-${organizations.size + 1}`),
            name: payload.name,
          });
          return [organization, new Map(organizations).set(organization.id, organization)];
        }),
      )
      .handle("getById", ({ params }) =>
        Ref.get(store).pipe(
          Effect.flatMap((organizations) => {
            const organization = organizations.get(params.id);
            return organization === undefined
              ? Effect.fail(new OrganizationNotFound())
              : Effect.succeed(organization);
          }),
        ),
      );
  }),
);

const makeClient = HttpApiTest.groups(SurveyBeatApi, ["organizations"]);

layer(Layer.mergeAll(OrganizationsHandlers, HttpServer.layerServices))("OrganizationsApi", (it) => {
  it.effect("creates and fetches an Organization", () =>
    Effect.gen(function* () {
      const client = yield* makeClient;
      const created = yield* client.organizations.create({ payload: { name: "Acme" } });
      const fetched = yield* client.organizations.getById({ params: { id: created.id } });
      assert.deepStrictEqual(fetched, created);
    }),
  );

  it.effect("fails with OrganizationNotFound for an unknown id", () =>
    Effect.gen(function* () {
      const client = yield* makeClient;
      const error = yield* client.organizations
        .getById({ params: { id: OrganizationId.make("missing") } })
        .pipe(Effect.flip);
      assert.strictEqual(error._tag, "OrganizationNotFound");
    }),
  );
});
