        times: 80,
      }),
    );
    assert.strictEqual(done.state?._tag, "Sent");
    assert.deepStrictEqual(
      done.captured.map(({ recipient, subject }) => ({ recipient, subject })),
      [{ recipient: "ada@example.com", subject: "You've been added to Platform" }],
