import { Clock, Context, Effect, Option } from "effect";
import type { SendId } from "../email/Email.ts";
import type { DirectoryCommand, DirectoryRejection, FollowUp, Viewed } from "./Directory.ts";
import type { PersonId } from "./Identity.ts";
import type { OrganizationId } from "./Organization.ts";
import { Forbidden } from "./SignIn.ts";
import type { Member } from "./SignInFlow.ts";
import { IdentityProvider, PeopleIndex } from "./SignInPorts.ts";
import {
  LastAdmin,
  LastLead,
  type OrganizationSettings,
  PersonNotFound,
  type TeamDetail,
  type TeamId,
  TeamNameTaken,
  TeamNotFound,
  type TeamSummary,
} from "./Team.ts";

/** What the Organization's Durable Object answers to a command once it has committed it, or why not. */
export type CommandResult =
  | { readonly _tag: "Rejected"; readonly rejection: DirectoryRejection }
  /** The follow-ups to run, with `QueueEmail` only for sends that are still pending. */
  | { readonly _tag: "Accepted"; readonly followUps: ReadonlyArray<FollowUp> };

/**
 * The People, Teams, and Memberships of each Organization, as its Durable Object holds them
 * (ADR 0006). Every call authorizes the actor from that object's own data, in the same
 * transaction as the change, so a removed Person or an ended Membership is refused at once.
 */
export interface OrganizationDirectoryShape {
  readonly run: (
    organizationId: OrganizationId,
    actorId: PersonId,
    command: DirectoryCommand,
    now: number,
  ) => Effect.Effect<CommandResult>;
  readonly teams: (
    organizationId: OrganizationId,
    actorId: PersonId,
  ) => Effect.Effect<Viewed<ReadonlyArray<TeamSummary>>>;
  readonly team: (
    organizationId: OrganizationId,
    actorId: PersonId,
    teamId: TeamId,
  ) => Effect.Effect<Viewed<TeamDetail>>;
  readonly settings: (
    organizationId: OrganizationId,
    actorId: PersonId,
  ) => Effect.Effect<Viewed<OrganizationSettings>>;
}

export class OrganizationDirectory extends Context.Service<OrganizationDirectory, OrganizationDirectoryShape>()(
  "@surveybeat/domain/OrganizationDirectory",
) {}

/** Hands a pending send to the email Queue consumer. Delivery is idempotent per send, so repeats are safe. */
export class EmailOutbox extends Context.Service<
  EmailOutbox,
  { readonly queue: (organizationId: OrganizationId, sendId: SendId) => Effect.Effect<void> }
>()("@surveybeat/domain/EmailOutbox") {}

export type DirectoryError = Forbidden | TeamNotFound | PersonNotFound | LastLead | LastAdmin | TeamNameTaken;

const fail = (rejection: DirectoryRejection): Effect.Effect<never, DirectoryError> => {
  switch (rejection._tag) {
    case "Forbidden":
      return Effect.fail(new Forbidden());
    case "TeamNotFound":
      return Effect.fail(new TeamNotFound());
    case "PersonNotFound":
      return Effect.fail(new PersonNotFound());
    case "LastLead":
      return Effect.fail(new LastLead({ teamId: rejection.teamId }));
    case "LastAdmin":
      return Effect.fail(new LastAdmin());
    case "TeamNameTaken":
      return Effect.fail(new TeamNameTaken());
  }
};

const viewed = <A>(view: Viewed<A>): Effect.Effect<A, DirectoryError> =>
  view._tag === "Viewed" ? Effect.succeed(view.value) : fail(view.rejection);

/** Runs one follow-up. Each is idempotent, and a failure leaves the rest for the retry to do. */
const followUp = Effect.fnUntraced(function* (organizationId: OrganizationId, step: FollowUp) {
  const index = yield* PeopleIndex;
  const identityProvider = yield* IdentityProvider;
  const workosOrganization = index.workosOrganizationOf(organizationId);
  switch (step._tag) {
    case "IndexPerson":
      return yield* index.putPerson({
        organizationId,
        personId: step.person.id,
        email: step.person.email,
        userId: Option.fromNullishOr(step.person.workosUserId),
      });
    case "UnindexPerson":
      return yield* index.removePerson(organizationId, step.personId);
    case "DeactivateWorkosMembership": {
      const workos = yield* workosOrganization;
      if (Option.isSome(workos)) yield* identityProvider.deactivateMembership(step.userId, workos.value);
      return;
    }
    case "SetWorkosRole": {
      const workos = yield* workosOrganization;
      if (Option.isSome(workos)) yield* identityProvider.setMembershipRole(step.userId, workos.value, step.role);
      return;
    }
    case "QueueEmail":
      return yield* (yield* EmailOutbox).queue(organizationId, step.sendId);
  }
});

/**
 * Runs a command as the signed-in Person: the Durable Object authorizes and commits it, then the
 * global index, WorkOS, and the email queue are put in step. Removal reaches WorkOS last, after
 * the Durable Object (which the per-request check asks) and the index already refuse the Person.
 * When WorkOS cannot be reached this fails `AuthUnavailable`; repeating the request finishes it.
 */
export const runDirectoryCommand = Effect.fnUntraced(function* (member: Member, command: DirectoryCommand) {
  const directory = yield* OrganizationDirectory;
  const organizationId = member.organization.id;
  const result = yield* directory.run(organizationId, member.personId, command, yield* Clock.currentTimeMillis);
  if (result._tag === "Rejected") return yield* fail(result.rejection);
  for (const step of result.followUps) yield* followUp(organizationId, step);
});

export const viewTeams = (member: Member) =>
  Effect.flatMap(OrganizationDirectory, (directory) =>
    Effect.flatMap(directory.teams(member.organization.id, member.personId), viewed),
  );

export const viewTeam = (member: Member, teamId: TeamId) =>
  Effect.flatMap(OrganizationDirectory, (directory) =>
    Effect.flatMap(directory.team(member.organization.id, member.personId, teamId), viewed),
  );

export const viewSettings = (member: Member) =>
  Effect.flatMap(OrganizationDirectory, (directory) =>
    Effect.flatMap(directory.settings(member.organization.id, member.personId), viewed),
  );

import { describe, expect, it } from "@effect/vitest";
import { PersonId } from "./Identity.ts";
import { type Action, type Actor, can, PERMISSIONS, type Resource, type TeamAction } from "./Permissions.ts";
import { type MembershipRole, TeamId } from "./Team.ts";

const team = TeamId.make("platform");
const otherTeam = TeamId.make("design");

const actor = (organizationAdmin: boolean, role?: MembershipRole): Actor => ({
  personId: PersonId.make("person"),
  organizationAdmin,
  roles: new Map(role === undefined ? [] : [[team, role]]),
});

/** The people the table is about: every role in `team`, an admin with and without a Membership, and outsiders. */
const ACTORS = {
  admin: actor(true),
  adminLead: actor(true, "lead"),
  lead: actor(false, "lead"),
  member: actor(false, "member"),
  viewer: actor(false, "viewer"),
  leadElsewhere: { ...actor(false), roles: new Map([[otherTeam, "lead" as const]]) },
  nobody: actor(false),
} satisfies Record<string, Actor>;
type Who = keyof typeof ACTORS;
const EVERYONE = Object.keys(ACTORS) as ReadonlyArray<Who>;

/**
 * SPEC §5.6: one row per action, listing exactly who may do it (to `team` for Team actions).
 * Everyone not listed is refused. An Organization admin administers but never reads Results
 * (ADR 0003), and a role in another Team grants nothing here.
 */
const TABLE: { readonly [A in Action]: ReadonlyArray<Who> } = {
  "organization.viewSettings": ["admin", "adminLead"],
  "organization.updateSettings": ["admin", "adminLead"],
  "organization.setAdmin": ["admin", "adminLead"],
  "organization.removePerson": ["admin", "adminLead"],
  "organization.listTeams": ["admin", "adminLead"],
  "organization.createTeam": ["admin", "adminLead"],
  "team.view": ["admin", "adminLead", "lead", "member", "viewer"],
  "team.update": ["admin", "adminLead"],
  "team.viewRoster": ["admin", "adminLead", "lead"],
  "team.addMember": ["admin", "adminLead", "lead"],
  "team.removeMember": ["admin", "adminLead", "lead"],
  "team.assignLead": ["admin", "adminLead"],
  "team.removeLead": ["admin", "adminLead"],
  "team.viewResults": ["adminLead", "lead", "member", "viewer"],
};

const isTeamAction = (action: Action): action is TeamAction => action.startsWith("team.");

const ask = (who: Who, action: Action): boolean => {
  const resource: Resource = isTeamAction(action) ? { _tag: "Team", teamId: team } : { _tag: "Organization" };
  // The table pairs each action with its own resource kind; `can`'s types enforce that for callers.
  return isTeamAction(action) && resource._tag === "Team"
    ? can(ACTORS[who], action, resource)
    : !isTeamAction(action) && resource._tag === "Organization"
      ? can(ACTORS[who], action, resource)
      : false;
};

const rows = (Object.keys(TABLE) as ReadonlyArray<Action>).flatMap((action) =>
  EVERYONE.map((who) => ({ action, who, allowed: TABLE[action].includes(who) })),
);

describe("the permission table", () => {
  it("covers every action the permission function knows", () => {
    expect(Object.keys(TABLE).sort()).toEqual(Object.keys(PERMISSIONS).sort());
  });

  it.each(rows)("$who → $action: $allowed", ({ who, action, allowed }) => {
    expect(ask(who, action)).toBe(allowed);
  });

  it("never lets an Organization admin without a Membership read a Team's Results", () => {
    expect(can(ACTORS.admin, "team.viewResults", { _tag: "Team", teamId: team })).toBe(false);
    expect(can(ACTORS.admin, "team.viewRoster", { _tag: "Team", teamId: team })).toBe(true);
  });

  it("grants a role only in its own Team", () => {
    expect(can(ACTORS.leadElsewhere, "team.addMember", { _tag: "Team", teamId: otherTeam })).toBe(true);
    expect(can(ACTORS.leadElsewhere, "team.addMember", { _tag: "Team", teamId: team })).toBe(false);
  });
});

import { describe, expect, it } from "@effect/vitest";
import { Option, Schema } from "effect";
import { EmailAddress } from "../email/Email.ts";
import {
  actorOf,
  applyChanges,
  type Decision,
  decide,
  type DirectoryCommand,
  type DirectoryState,
  type NewMember,
  settingsView,
  teamsView,
  teamView,
} from "./Directory.ts";
import { PersonId, WorkosUserId } from "./Identity.ts";
import { MembershipId, MinimumGroupSize, TeamId, TimeZone } from "./Team.ts";

const ADMIN = PersonId.make("admin");
const DAY = 86_400_000;

const initial: DirectoryState = {
  organizationName: "Acme",
  minimumGroupSize: 4,
  people: [
    {
      id: ADMIN,
      email: EmailAddress.make("admin@example.com"),
      workosUserId: WorkosUserId.make("user_admin"),
      organizationAdmin: true,
      removedAt: null,
    },
  ],
  teams: [],
  memberships: [],
};

/** A small Organization to run commands against, keeping every committed state. */
class World {
  state = initial;
  private ids = 0;
  now = 1_000 * DAY;

  newMember(email: string): NewMember {
    const n = ++this.ids;
    return {
      email: EmailAddress.make(email),
      personId: PersonId.make(`person-${n}`),
      membershipId: MembershipId.make(`membership-${n}`),
      signInUrl: "https://app.surveybeat.app/",
    };
  }

  run(actor: PersonId, command: DirectoryCommand): Decision {
    const decision = decide(this.state, actor, command, this.now);
    if (decision._tag === "Accepted") this.state = applyChanges(this.state, decision.changes);
    return decision;
  }

  /** Runs a command that must succeed. */
  ok(actor: PersonId, command: DirectoryCommand): Extract<Decision, { _tag: "Accepted" }> {
    const decision = this.run(actor, command);
    if (decision._tag !== "Accepted") throw new Error(`${command._tag} rejected: ${decision.rejection._tag}`);
    return decision;
  }

  createTeam(name: string, leadEmail: string): TeamId {
    const teamId = TeamId.make(`team-${++this.ids}`);
    this.ok(ADMIN, {
      _tag: "CreateTeam",
      teamId,
      name,
      timeZone: TimeZone.make("Europe/Berlin"),
      lead: this.newMember(leadEmail),
    });
    return teamId;
  }

  add(actor: PersonId, teamId: TeamId, email: string, role: "lead" | "member" = "member") {
    return this.run(actor, { _tag: "AddMember", teamId, role, member: this.newMember(email) });
  }

  personWith(email: string): PersonId {
    const person = this.state.people.find((each) => each.email === email);
    if (person === undefined) throw new Error(`no Person ${email}`);
    return person.id;
  }

  roster(teamId: TeamId) {
    const view = teamView(this.state, ADMIN, teamId);
    if (view._tag !== "Viewed") throw new Error("no roster");
    return view.value.roster.map(({ email, role }) => `${role} ${email}`);
  }
}

const rejection = (decision: Decision) => (decision._tag === "Rejected" ? decision.rejection._tag : "Accepted");

describe("adding members by email", () => {
  it("creates a Person with email only, a Membership, and the 'You've been added' email", () => {
    const world = new World();
    const platform = world.createTeam("Platform", "grace@example.com");
    const grace = world.personWith("grace@example.com");
    const decision = world.add(grace, platform, " Ada@Example.com ");
    if (decision._tag !== "Accepted") throw new Error("rejected");

    const ada = world.state.people.find((person) => person.email === "ada@example.com");
    expect(ada).toMatchObject({ workosUserId: null, organizationAdmin: false, removedAt: null });
    expect(world.roster(platform)).toEqual(["lead grace@example.com", "member ada@example.com"]);
    expect(decision.changes).toContainEqual({
      _tag: "EmailRequested",
      sendId: expect.stringMatching(/^added-/),
      recipient: "ada@example.com",
      email: {
        _tag: "AddedToTeam",
        teamName: "Platform",
        leadName: "grace@example.com",
        signInUrl: "https://app.surveybeat.app/",
      },
    });
    expect(decision.followUps.map((step) => step._tag)).toEqual(["IndexPerson", "QueueEmail"]);
  });

  it("reuses the Person an email already has, in any Team", () => {
    const world = new World();
    const platform = world.createTeam("Platform", "grace@example.com");
    const design = world.createTeam("Design", "linus@example.com");
    world.add(ADMIN, platform, "ada@example.com");
    world.add(ADMIN, design, "ada@example.com");
    expect(world.state.people.filter((person) => person.email === "ada@example.com")).toHaveLength(1);
  });

  it("changes nothing for someone already in the Team, but repeats the follow-ups", () => {
    const world = new World();
    const platform = world.createTeam("Platform", "grace@example.com");
    world.add(ADMIN, platform, "ada@example.com");
    const again = world.add(ADMIN, platform, "ada@example.com");
    expect(again).toMatchObject({ _tag: "Accepted", changes: [] });
    if (again._tag === "Accepted") {
      expect(again.followUps.map((step) => step._tag)).toEqual(["IndexPerson", "QueueEmail"]);
    }
    // Adding a Lead as a member does not demote them.
    expect(world.add(ADMIN, platform, "grace@example.com")).toMatchObject({ changes: [] });
    expect(world.roster(platform)).toEqual(["lead grace@example.com", "member ada@example.com"]);
  });

  it("lets only an admin or that Team's Lead add members, and only an admin assign Leads", () => {
    const world = new World();
    const platform = world.createTeam("Platform", "grace@example.com");
    const design = world.createTeam("Design", "linus@example.com");
    world.add(ADMIN, platform, "ada@example.com");
    const grace = world.personWith("grace@example.com");
    const ada = world.personWith("ada@example.com");
    const linus = world.personWith("linus@example.com");

    expect(rejection(world.add(ada, platform, "eve@example.com"))).toBe("Forbidden");
    expect(rejection(world.add(linus, platform, "eve@example.com"))).toBe("Forbidden");
    expect(rejection(world.add(grace, platform, "eve@example.com", "lead"))).toBe("Forbidden");
    expect(rejection(world.add(grace, design, "eve@example.com"))).toBe("Forbidden");
    expect(rejection(world.add(grace, platform, "eve@example.com"))).toBe("Accepted");
  });

  it("refuses a Team that does not exist without telling a non-admin whether it does", () => {
    const world = new World();
    const platform = world.createTeam("Platform", "grace@example.com");
    const grace = world.personWith("grace@example.com");
    const missing = TeamId.make("missing");
    expect(rejection(world.add(ADMIN, missing, "eve@example.com"))).toBe("TeamNotFound");
    expect(rejection(world.add(grace, missing, "eve@example.com"))).toBe("Forbidden");
    expect(rejection(world.add(grace, platform, "eve@example.com"))).toBe("Accepted");
  });
});

describe("Leads", () => {
  it("creates every Team with a Lead, and makes a member Lead by ending one Membership and starting another", () => {
    const world = new World();
    const platform = world.createTeam("Platform", "grace@example.com");
    world.add(ADMIN, platform, "ada@example.com");
    world.now += DAY;
    world.ok(ADMIN, {
      _tag: "AddMember",
      teamId: platform,
      role: "lead",
      member: world.newMember("ada@example.com"),
    });
    expect(world.roster(platform)).toEqual(["lead ada@example.com", "lead grace@example.com"]);
    const ada = world.personWith("ada@example.com");
    const history = world.state.memberships.filter((membership) => membership.personId === ada);
    expect(history.map(({ role, startedAt, endedAt }) => ({ role, startedAt, endedAt }))).toEqual([
      { role: "member", startedAt: 1_000 * DAY, endedAt: 1_001 * DAY },
      { role: "lead", startedAt: 1_001 * DAY, endedAt: null },
    ]);
  });

  it("never removes the last Lead, either as Lead or as member", () => {
    const world = new World();
    const platform = world.createTeam("Platform", "grace@example.com");
    const grace = world.personWith("grace@example.com");
    const removeLead = (personId: PersonId) =>
      world.run(ADMIN, {
        _tag: "RemoveLead",
        teamId: platform,
        personId,
        membershipId: MembershipId.make(`demoted-${personId}`),
      });

    expect(world.run(ADMIN, { _tag: "RemoveMember", teamId: platform, personId: grace })).toEqual({
      _tag: "Rejected",
      rejection: { _tag: "LastLead", teamId: platform },
    });
    expect(rejection(removeLead(grace))).toBe("LastLead");
    expect(rejection(world.run(ADMIN, { _tag: "RemovePerson", personId: grace }))).toBe("LastLead");

    world.add(ADMIN, platform, "ada@example.com", "lead");
    expect(rejection(removeLead(grace))).toBe("Accepted");
    expect(world.roster(platform)).toEqual(["lead ada@example.com", "member grace@example.com"]);
    expect(rejection(removeLead(world.personWith("ada@example.com")))).toBe("LastLead");
  });

  it("lets a Lead remove members but not another Lead", () => {
    const world = new World();
    const platform = world.createTeam("Platform", "grace@example.com");
    world.add(ADMIN, platform, "linus@example.com", "lead");
    world.add(ADMIN, platform, "ada@example.com");
    const grace = world.personWith("grace@example.com");
    const linus = world.personWith("linus@example.com");
    const ada = world.personWith("ada@example.com");
    expect(rejection(world.run(grace, { _tag: "RemoveMember", teamId: platform, personId: linus }))).toBe(
      "Forbidden",
    );
    expect(rejection(world.run(grace, { _tag: "RemoveMember", teamId: platform, personId: ada }))).toBe(
      "Accepted",
    );
    expect(rejection(world.run(ADMIN, { _tag: "RemoveMember", teamId: platform, personId: linus }))).toBe(
      "Accepted",
    );
  });
});

describe("removing", () => {
  it("ends a member's Membership on that date and keeps the Person and their history", () => {
    const world = new World();
    const platform = world.createTeam("Platform", "grace@example.com");
    world.add(ADMIN, platform, "ada@example.com");
    const ada = world.personWith("ada@example.com");
    world.now += 3 * DAY;
    world.ok(ADMIN, { _tag: "RemoveMember", teamId: platform, personId: ada });

    expect(world.roster(platform)).toEqual(["lead grace@example.com"]);
    expect(world.state.people.find((person) => person.id === ada)?.removedAt).toBeNull();
    expect(world.state.memberships.find((membership) => membership.personId === ada)).toMatchObject({
      startedAt: 1_000 * DAY,
      endedAt: 1_003 * DAY,
    });
    expect(rejection(world.run(ADMIN, { _tag: "RemoveMember", teamId: platform, personId: ada }))).toBe(
      "PersonNotFound",
    );
  });

  it("removes a Person from the Organization: every Membership ends, the record and history stay", () => {
    const world = new World();
    const platform = world.createTeam("Platform", "grace@example.com");
    const design = world.createTeam("Design", "linus@example.com");
    world.add(ADMIN, platform, "ada@example.com");
    world.add(ADMIN, design, "ada@example.com");
    const ada = world.personWith("ada@example.com");
    world.now += DAY;
    const removed = world.ok(ADMIN, { _tag: "RemovePerson", personId: ada });

    expect(world.state.people.find((person) => person.id === ada)?.removedAt).toBe(1_001 * DAY);
    const history = world.state.memberships.filter((membership) => membership.personId === ada);
    expect(history.map((membership) => membership.endedAt)).toEqual([1_001 * DAY, 1_001 * DAY]);
    expect(Option.isNone(actorOf(world.state, ada))).toBe(true);
    // Never signed in: only the index needs to forget them, WorkOS has no membership.
    expect(removed.followUps).toEqual([{ _tag: "UnindexPerson", personId: ada }]);
  });

  it("deactivates the WorkOS membership of a signed-in Person, and repeats the follow-ups on a retry", () => {
