      ...world.state,
      people: [
        ...world.state.people,
        {
          id: PersonId.make("ada"),
          email: EmailAddress.make("ada@example.com"),
          workosUserId: WorkosUserId.make("user_ada"),
          organizationAdmin: false,
          removedAt: null,
        },
      ],
    };
