    expect(world.ok(ADMIN, { _tag: "RemovePerson", personId: PersonId.make("ada") })).toEqual({
      _tag: "Accepted",
      changes: [],
      followUps,
    });
  });

  it("restores a removed Person added back, as a plain member with their history", () => {
    const world = new World();
