import { Button } from "@base-ui/react/button";
import { Field } from "@base-ui/react/field";
import { Form } from "@base-ui/react/form";
import {
  EmailAddress,
  type MembershipRole,
  type OrganizationSettings,
  PersonId,
  type TeamDetail,
  TeamId,
  type TeamSummary,
  TimeZone,
} from "@surveybeat/domain";
import { type ReactNode, useCallback, useEffect, useState } from "react";
import { formatDate, message } from "../messages/index.ts";
import { call, type Failure, type Outcome } from "./directory.ts";

export const buttonClass = "rounded bg-black px-4 py-2 text-white disabled:opacity-50";
const quietButton = "text-sm text-gray-700 underline disabled:opacity-50";
const inputClass = "mt-1 w-full rounded border px-3 py-2";

/** The signed-in screens, addressed by the URL hash so a reload stays put. */
type Route = { readonly _tag: "Teams" } | { readonly _tag: "Team"; readonly id: TeamId } | { readonly _tag: "Settings" };

const parseRoute = (hash: string): Route => {
  const team = /^#\/teams\/([^/]+)$/.exec(hash);
  if (team?.[1] !== undefined) return { _tag: "Team", id: TeamId.make(decodeURIComponent(team[1])) };
  if (hash === "#/settings") return { _tag: "Settings" };
  return { _tag: "Teams" };
};

export const teamHref = (id: string) => `#/teams/${encodeURIComponent(id)}`;

export function useRoute(): Route {
  const [route, setRoute] = useState(() => parseRoute(window.location.hash));
  useEffect(() => {
    const onChange = () => setRoute(parseRoute(window.location.hash));
    window.addEventListener("hashchange", onChange);
    return () => window.removeEventListener("hashchange", onChange);
  }, []);
  return route;
}

/** Loads a view, and reloads it after each change. */
function useView<A>(load: () => Promise<Outcome<A>>) {
  const [outcome, setOutcome] = useState<Outcome<A> | undefined>(undefined);
  const reload = useCallback(() => void load().then(setOutcome), [load]);
  useEffect(reload, [reload]);
  return { outcome, reload };
}

function Problem({ failure }: { readonly failure: Failure | undefined }) {
  if (failure === undefined) return null;
  return (
    <p role="alert" className="mt-2 text-red-700">
      {message(`error.${failure}`)}
    </p>
  );
}

/** Runs a change, shows why it failed, and reloads the view when it worked. */
function useChange(onDone: () => void) {
  const [busy, setBusy] = useState(false);
  const [failure, setFailure] = useState<Failure | undefined>(undefined);
  const run = (change: () => Promise<Outcome<unknown>>, after?: () => void) => {
    setBusy(true);
    setFailure(undefined);
    void change().then((outcome) => {
      setBusy(false);
      if (!outcome.ok) return setFailure(outcome.failure);
      after?.();
      onDone();
    });
  };
  return { busy, failure, run };
}

function TextField(props: {
  readonly label: string;
  readonly value: string;
  readonly onChange: (value: string) => void;
  readonly type?: "email" | "text";
}) {
  return (
    <Field.Root>
      <Field.Label className="block text-sm font-medium">{props.label}</Field.Label>
      <Field.Control
        required
        type={props.type ?? "text"}
        value={props.value}
        onValueChange={props.onChange}
        className={inputClass}
      />
    </Field.Root>
  );
}

const timeZones = (): ReadonlyArray<string> => {
  const names = Intl.supportedValuesOf("timeZone");
  return names.includes("UTC") ? names : ["UTC", ...names];
};

const browserTimeZone = () => Intl.DateTimeFormat().resolvedOptions().timeZone;

function TimeZoneField({ value, onChange }: { readonly value: string; readonly onChange: (value: string) => void }) {
  return (
    <Field.Root>
      <Field.Label className="block text-sm font-medium">{message("teams.create.timeZone")}</Field.Label>
      <select value={value} onChange={(event) => onChange(event.target.value)} className={inputClass}>
        {timeZones().map((name) => (
          <option key={name} value={name}>
            {name}
          </option>
        ))}
      </select>
    </Field.Root>
  );
}

/** One-field email forms: add a member, assign a Lead. */
function EmailForm(props: {
  readonly label: string;
  readonly action: string;
  readonly submit: (email: EmailAddress) => Promise<Outcome<unknown>>;
  readonly onDone: () => void;
}) {
  const [email, setEmail] = useState("");
  const [added, setAdded] = useState(false);
  const { busy, failure, run } = useChange(props.onDone);
  return (
    <Form
      className="mt-4 flex flex-col gap-2"
      onSubmit={(event) => {
        event.preventDefault();
        setAdded(false);
        run(
          () => props.submit(EmailAddress.make(email.trim())),
          () => {
            setEmail("");
            setAdded(true);
          },
        );
      }}
    >
      <TextField label={props.label} type="email" value={email} onChange={setEmail} />
      <Button type="submit" disabled={busy || email.trim() === ""} className={buttonClass}>
        {props.action}
      </Button>
      <Problem failure={failure} />
      {added ? <p className="text-sm text-gray-600">{message("team.added")}</p> : null}
    </Form>
  );
}

const roleName = (role: MembershipRole) => message(`role.${role}`);

export function Shell({
  title,
  organizationAdmin,
  children,
  signOut,
}: {
  readonly title: string;
  readonly organizationAdmin: boolean;
  readonly children: ReactNode;
  readonly signOut: ReactNode;
}) {
  return (
    <main className="mx-auto max-w-2xl p-6">
      <header className="flex flex-wrap items-baseline justify-between gap-2">
        <h1 className="text-2xl font-semibold">{title}</h1>
        <nav className="flex gap-4 text-sm">
          <a href="#/" className="underline">
            {message("nav.teams")}
          </a>
          {organizationAdmin ? (
            <a href="#/settings" className="underline">
              {message("nav.settings")}
            </a>
          ) : null}
        </nav>
      </header>
      {children}
      {signOut}
    </main>
  );
}

function CreateTeam({ onDone }: { readonly onDone: () => void }) {
  const [name, setName] = useState("");
  const [timeZone, setTimeZone] = useState(browserTimeZone);
  const [leadEmail, setLeadEmail] = useState("");
  const { busy, failure, run } = useChange(onDone);
  return (
    <section className="mt-8">
      <h2 className="text-lg font-semibold">{message("teams.create.title")}</h2>
      <Form
        className="mt-2 flex flex-col gap-3"
        onSubmit={(event) => {
          event.preventDefault();
          run(
            () =>
              call((api) =>
                api.createTeam({
                  payload: {
                    name: name.trim(),
                    timeZone: TimeZone.make(timeZone),
                    leadEmail: EmailAddress.make(leadEmail.trim()),
                  },
                }),
              ).then((outcome) => {
                if (outcome.ok) window.location.hash = teamHref(outcome.value.team.id);
                return outcome;
              }),
            () => {
              setName("");
              setLeadEmail("");
            },
          );
        }}
      >
        <TextField label={message("teams.create.name")} value={name} onChange={setName} />
        <TimeZoneField value={timeZone} onChange={setTimeZone} />
        <TextField label={message("teams.create.leadEmail")} type="email" value={leadEmail} onChange={setLeadEmail} />
        <Button type="submit" disabled={busy || name.trim() === "" || leadEmail.trim() === ""} className={buttonClass}>
          {message("teams.create.action")}
        </Button>
        <Problem failure={failure} />
      </Form>
    </section>
  );
}

const loadTeams = () => call((api) => api.listTeams());

export function TeamsScreen({ organizationAdmin }: { readonly organizationAdmin: boolean }) {
  const { outcome, reload } = useView(loadTeams);
  if (outcome === undefined) return <p className="mt-4">{message("app.loading")}</p>;
  if (!outcome.ok) return <Problem failure={outcome.failure} />;
  const teams: ReadonlyArray<TeamSummary> = outcome.value;
  return (
    <>
      <h2 className="mt-6 text-lg font-semibold">{message("teams.title")}</h2>
      {teams.length === 0 ? <p className="mt-2 text-gray-600">{message("teams.empty")}</p> : null}
      <ul className="mt-2 flex flex-col gap-2">
        {teams.map((team) => (
          <li key={team.id} className="rounded border p-3">
            <a href={teamHref(team.id)} className="font-medium underline">
              {team.name}
            </a>
            {team.yourRole === null ? null : (
              <span className="ml-2 text-sm text-gray-600">
                {message("teams.yourRole", { role: roleName(team.yourRole) })}
              </span>
            )}
          </li>
        ))}
      </ul>
      {organizationAdmin ? <CreateTeam onDone={reload} /> : null}
    </>
  );
}

function RenameTeam({ detail, onDone }: { readonly detail: TeamDetail; readonly onDone: () => void }) {
  const [name, setName] = useState(detail.team.name);
  const [timeZone, setTimeZone] = useState<string>(detail.team.timeZone);
  const { busy, failure, run } = useChange(onDone);
  return (
    <section className="mt-6">
      <h3 className="font-semibold">{message("team.rename.title")}</h3>
      <Form
        className="mt-2 flex flex-col gap-3"
        onSubmit={(event) => {
          event.preventDefault();
          run(() =>
            call((api) =>
              api.updateTeam({
                params: { teamId: detail.team.id },
                payload: { name: name.trim(), timeZone: TimeZone.make(timeZone) },
              }),
            ),
          );
        }}
      >
        <TextField label={message("teams.create.name")} value={name} onChange={setName} />
        <TimeZoneField value={timeZone} onChange={setTimeZone} />
        <Button type="submit" disabled={busy || name.trim() === ""} className={buttonClass}>
          {message("team.rename.action")}
        </Button>
        <Problem failure={failure} />
      </Form>
    </section>
  );
}

function Roster({ detail, onDone }: { readonly detail: TeamDetail; readonly onDone: () => void }) {
  const { busy, failure, run } = useChange(onDone);
  const teamId = detail.team.id;
  return (
    <section className="mt-6">
      <h3 className="font-semibold">{message("team.roster")}</h3>
      <Problem failure={failure} />
      <ul className="mt-2 flex flex-col gap-2">
        {detail.roster.map((entry) => (
          <li key={entry.personId} className="flex flex-wrap items-center gap-x-3 gap-y-1 rounded border p-3">
            <span className="font-medium">{entry.email}</span>
            <span className="text-sm text-gray-600">{roleName(entry.role)}</span>
            <span className="text-sm text-gray-500">
              {message("team.since", { date: formatDate(new Date(entry.since)) })}
            </span>
            <span className="ml-auto flex gap-3">
              {entry.role === "lead" && detail.may.manageLeads ? (
                <Button
                  disabled={busy}
                  className={quietButton}
                  onClick={() =>
                    run(() => call((api) => api.removeLead({ params: { teamId, personId: entry.personId } })))
                  }
                >
                  {message("team.removeLead")}
                </Button>
              ) : null}
              {(entry.role === "lead" ? detail.may.manageLeads : detail.may.manageMembers) ? (
                <Button
                  disabled={busy}
                  className={quietButton}
                  onClick={() =>
                    run(() => call((api) => api.removeMember({ params: { teamId, personId: entry.personId } })))
                  }
                >
                  {message("team.removeMember")}
                </Button>
              ) : null}
            </span>
          </li>
        ))}
      </ul>
    </section>
  );
}

export function TeamScreen({ id }: { readonly id: TeamId }) {
  const load = useCallback(() => call((api) => api.getTeam({ params: { teamId: id } })), [id]);
  const { outcome, reload } = useView(load);
  if (outcome === undefined) return <p className="mt-4">{message("app.loading")}</p>;
  if (!outcome.ok) return <Problem failure={outcome.failure} />;
  const detail = outcome.value;
  const teamId = detail.team.id;
  return (
    <>
      <p className="mt-4 text-sm">
        <a href="#/" className="underline">
          {message("team.back")}
        </a>
      </p>
      <h2 className="mt-2 text-xl font-semibold">{detail.team.name}</h2>
      <p className="text-sm text-gray-600">{message("team.timeZone", { timeZone: detail.team.timeZone })}</p>
      {detail.may.viewResults ? null : <p className="mt-2 text-sm text-gray-600">{message("team.noResultsAccess")}</p>}
      <Roster detail={detail} onDone={reload} />
      {detail.may.manageMembers ? (
        <EmailForm
          label={message("team.addMember.label")}
          action={message("team.addMember.action")}
          submit={(email) => call((api) => api.addMember({ params: { teamId }, payload: { email } }))}
          onDone={reload}
        />
      ) : null}
      {detail.may.manageLeads ? (
        <EmailForm
          label={message("team.assignLead.label")}
          action={message("team.assignLead.action")}
          submit={(email) => call((api) => api.assignLead({ params: { teamId }, payload: { email } }))}
          onDone={reload}
        />
      ) : null}
      {detail.may.update ? <RenameTeam key={`${detail.team.name}/${detail.team.timeZone}`} detail={detail} onDone={reload} /> : null}
    </>
  );
}

function MinimumGroupSizeForm({ settings, onDone }: { readonly settings: OrganizationSettings; readonly onDone: () => void }) {
  const [value, setValue] = useState(String(settings.minimumGroupSize));
  const [saved, setSaved] = useState(false);
  const { busy, failure, run } = useChange(onDone);
  return (
    <Form
      className="mt-4 flex flex-col gap-2"
      onSubmit={(event) => {
        event.preventDefault();
        setSaved(false);
        run(
          () => call((api) => api.updateSettings({ payload: { minimumGroupSize: Number(value) } })),
          () => setSaved(true),
        );
      }}
    >
      <Field.Root>
        <Field.Label className="block text-sm font-medium">{message("settings.minimumGroupSize")}</Field.Label>
        <Field.Control
          required
          type="number"
          min={3}
          max={100}
          step={1}
          value={value}
          onValueChange={setValue}
          className={inputClass}
        />
        <Field.Description className="mt-1 text-sm text-gray-600">
          {message("settings.minimumGroupSize.help")}
        </Field.Description>
      </Field.Root>
      <Button type="submit" disabled={busy} className={buttonClass}>
        {message("settings.save")}
      </Button>
      <Problem failure={failure} />
      {saved ? <p className="text-sm text-gray-600">{message("settings.saved")}</p> : null}
    </Form>
  );
}

const loadSettings = () => call((api) => api.getSettings());

export function SettingsScreen() {
  const { outcome, reload } = useView(loadSettings);
  const { busy, failure, run } = useChange(reload);
  if (outcome === undefined) return <p className="mt-4">{message("app.loading")}</p>;
  if (!outcome.ok) return <Problem failure={outcome.failure} />;
  const settings = outcome.value;
  return (
    <>
      <h2 className="mt-6 text-lg font-semibold">{message("settings.title")}</h2>
      <MinimumGroupSizeForm key={settings.minimumGroupSize} settings={settings} onDone={reload} />
      <h3 className="mt-8 font-semibold">{message("settings.people")}</h3>
      <Problem failure={failure} />
      <ul className="mt-2 flex flex-col gap-2">
        {settings.people.map((person) => {
          const personId = PersonId.make(person.personId);
          return (
            <li key={person.personId} className="flex flex-wrap items-center gap-x-3 gap-y-1 rounded border p-3">
              <span className="font-medium">{person.email}</span>
              {person.organizationAdmin ? (
                <span className="text-sm text-gray-600">{message("settings.admin")}</span>
              ) : null}
              {person.linked ? null : (
                <span className="text-sm text-gray-500">{message("settings.notSignedInYet")}</span>
              )}
              <span className="ml-auto flex gap-3">
                <Button
                  disabled={busy}
                  className={quietButton}
                  onClick={() =>
                    run(() =>
                      call((api) =>
                        person.organizationAdmin
                          ? api.revokeAdmin({ params: { personId } })
                          : api.grantAdmin({ params: { personId } }),
                      ),
                    )
                  }
                >
                  {person.organizationAdmin ? message("settings.revokeAdmin") : message("settings.makeAdmin")}
                </Button>
                <Button
                  disabled={busy}
                  className={quietButton}
                  onClick={() => run(() => call((api) => api.removePerson({ params: { personId } })))}
                >
                  {message("settings.removePerson")}
                </Button>
              </span>
            </li>
          );
        })}
      </ul>
    </>
  );
}

